package agent

import (
	"fmt"
	"sync"
	"time"
)

type Connection struct {
	ID     int
	Active bool
	LastUsed time.Time
}

type ConnectionPool struct {
	mu          sync.Mutex
	conns       []*Connection
	maxSize     int
	evictHook   func(conn *Connection, activeCount int)
}

type MetricEntry struct {
	Timestamp time.Time
	Message   string
	ConnID    int
}

type MonitorAgent struct {
	pool    *ConnectionPool
	metrics []MetricEntry
	metricsMu sync.Mutex
}

func NewConnectionPool(maxSize int) *ConnectionPool {
	p := &ConnectionPool{
		conns:   make([]*Connection, 0, maxSize),
		maxSize: maxSize,
	}
	p.evictHook = p.defaultEvictHook
	return p
}

func (p *ConnectionPool) defaultEvictHook(conn *Connection, activeCount int) {
	// Log eviction with pre-computed stats (no callback into pool)
	fmt.Printf("evicted conn %d, active remaining: %d\n", conn.ID, activeCount)
}

func (p *ConnectionPool) ActiveCount() int {
	p.mu.Lock()
	defer p.mu.Unlock()
	count := 0
	for _, c := range p.conns {
		if c.Active {
			count++
		}
	}
	return count
}

func (p *ConnectionPool) activeCountLocked() int {
	count := 0
	for _, c := range p.conns {
		if c.Active {
			count++
		}
	}
	return count
}

func (p *ConnectionPool) Acquire() (*Connection, error) {
	p.mu.Lock()
	defer p.mu.Unlock()

	for _, c := range p.conns {
		if !c.Active {
			c.Active = true
			c.LastUsed = time.Now()
			return c, nil
		}
	}

	if len(p.conns) < p.maxSize {
		c := &Connection{ID: len(p.conns) + 1, Active: true, LastUsed: time.Now()}
		p.conns = append(p.conns, c)
		return c, nil
	}

	// Evict oldest connection under pressure
	oldest := p.conns[0]
	for _, c := range p.conns[1:] {
		if c.LastUsed.Before(oldest.LastUsed) {
			oldest = c
		}
	}
	oldest.Active = false
	// Compute active count before calling hook (no reentrant lock acquisition)
	active := p.activeCountLocked()
	p.evictHook(oldest, active)
	oldest.Active = true
	oldest.LastUsed = time.Now()
	return oldest, nil
}

func (p *ConnectionPool) Release(conn *Connection) {
	p.mu.Lock()
	defer p.mu.Unlock()
	conn.Active = false
}

func (p *ConnectionPool) SetEvictHook(hook func(*Connection, int)) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.evictHook = hook
}

func NewMonitorAgent(poolSize int) *MonitorAgent {
	agent := &MonitorAgent{
		pool:    NewConnectionPool(poolSize),
		metrics: make([]MetricEntry, 0),
	}
	return agent
}

func (a *MonitorAgent) LogMetric(msg string) error {
	conn, err := a.pool.Acquire()
	if err != nil {
		return err
	}
	defer a.pool.Release(conn)

	a.metricsMu.Lock()
	a.metrics = append(a.metrics, MetricEntry{
		Timestamp: time.Now(),
		Message:   msg,
		ConnID:    conn.ID,
	})
	a.metricsMu.Unlock()
	return nil
}

func (a *MonitorAgent) FlushMetrics() []MetricEntry {
	a.metricsMu.Lock()
	defer a.metricsMu.Unlock()
	result := make([]MetricEntry, len(a.metrics))
	copy(result, a.metrics)
	a.metrics = a.metrics[:0]
	return result
}

func (a *MonitorAgent) HealthCheck() bool {
	conn, err := a.pool.Acquire()
	if err != nil {
		return false
	}
	defer a.pool.Release(conn)
	return conn.Active
}
